pub const CLI_OPERATION_COUNT: usize = 396;
pub fn find_cli_operation(namespace: &str, operation_id: &str) -> Option<&'static CliOperation> {
    CLI_OPERATIONS
        .iter()
        .find(|op| op.provider_namespace == namespace && op.operation_id == operation_id)
}
pub fn operations_for_namespace(namespace: &str) -> impl Iterator<Item = &'static CliOperation> {
    CLI_OPERATIONS
        .iter()
        .filter(move |op| op.provider_namespace == namespace)
}

/// Fail-closed mutation gate for CLI call paths.
pub fn operation_requires_confirmation(namespace: &str, operation_id: &str) -> bool {
    match find_cli_operation(namespace, operation_id) {
        Some(op) => op.requires_confirmation,
        // Unknown/missing metadata fails closed.
        None => true,
    }
}
